const std = @import("std");

pub fn reverseSlice(slice: []u8) void {
    var i: usize = 0;
    var j: usize = slice.len - 1;
    while (i < j) : ({
        i += 1;
        j -= 1;
    }) {
        const temp = slice[i];
        slice[i] = slice[j];
        slice[j] = temp;
    }
}

